import raw from "@/data/pikadoku-catalog.json";
import { PDK_FAMILIES, type PdkFamily } from "./types";

/**
 * Client-safe list of Pikadoku's categories (labels only, never answers), in
 * the order lib/pikadoku/categories builds them. Generated by
 * scripts/pikadoku-catalog.ts.
 *
 * A board's ticked categories are packed against this order: one bit per
 * category, six to a character of base64url. The same pack goes in the API
 * requests and the "Share this grid" link.
 */
export type PdkCatalogRow = [id: string, label: string, family: string, classic: 0 | 1];
export interface PdkCatalogEntry {
  id: string;
  label: string;
  family: PdkFamily;
  /** In PokeDoku's mix: what Unlimited ticks by default. */
  classic: boolean;
}

export const FAMILY_LETTER: Record<PdkFamily, string> = { types: "t", regions: "r", evolution: "e", moves: "m", abilities: "a", other: "o" };
const LETTER_FAMILY = Object.fromEntries(PDK_FAMILIES.map((f) => [FAMILY_LETTER[f], f])) as Record<string, PdkFamily>;

export const PDK_CATALOG: PdkCatalogEntry[] = (raw as PdkCatalogRow[]).map(([id, label, fam, classic]) => ({ id, label, family: LETTER_FAMILY[fam], classic: classic === 1 }));
const INDEX = new Map(PDK_CATALOG.map((c, i) => [c.id, i]));

const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
/** Characters in a pack: one per six categories. */
export const PICK_LENGTH = Math.ceil(PDK_CATALOG.length / 6);
export const PICK_RE = new RegExp(`^[A-Za-z0-9_-]{${PICK_LENGTH}}$`);

/** Packs a set of category ids (unknown ids are dropped). */
export function encodePick(ids: Iterable<string>): string {
  const bits = new Uint8Array(PICK_LENGTH);
  for (const id of ids) {
    const i = INDEX.get(id);
    if (i !== undefined) bits[Math.floor(i / 6)] |= 1 << i % 6;
  }
  return Array.from(bits, (b) => ALPHABET[b]).join("");
}

/** The category ids in a pack, in catalog order; null for anything that isn't a pack of this catalog. */
export function decodePick(pick: unknown): string[] | null {
  if (typeof pick !== "string" || !PICK_RE.test(pick)) return null;
  const out: string[] = [];
  for (let c = 0; c < pick.length; c++) {
    const v = ALPHABET.indexOf(pick[c]);
    for (let b = 0; b < 6; b++) if (v & (1 << b) && c * 6 + b < PDK_CATALOG.length) out.push(PDK_CATALOG[c * 6 + b].id);
  }
  return out;
}

/** What Unlimited ticks out of the box: PokeDoku's mix, the categories Unlimited always dealt from. */
export const DEFAULT_PICK_IDS: readonly string[] = PDK_CATALOG.filter((c) => c.classic).map((c) => c.id);
